SELECT /* Common.retrieveUserAccessList */ distinct lp.program_id || '/' || lp.system_service_id AS "PROG_SERV_ID" FROM lgcom_user_role_n_v lur ,lgcom_program_access_n lp ,lgcom_program_service_n ls ,lgcom_menu_m lm WHERE lur.role_code = lp.role_code AND lp.program_id = lm.program_id AND lp.program_id = ls.program_id AND lp.system_service_id = ls.system_service_id AND ls.control_flag = 'Y'
AND NVL(lur.apply_start_date, SYSDATE) <= SYSDATE AND NVL(lur.apply_end_date, SYSDATE) >= SYSDATE AND NVL(lp.apply_start_date, SYSDATE) <= SYSDATE AND NVL(lp.apply_end_date, SYSDATE) >= SYSDATE
AND lur.application_user_id = #{applicationUserId}
AND lm.menu_id = #{menuId}
AND lp.program_id = #{programId} AND lp.system_service_id = #{systemServiceId}
UNION ALL SELECT ls.program_id || '/' || ls.system_service_id AS "PROG_SERV_ID" FROM lgcom_program_service_n ls ,lgcom_menu_m lm WHERE ls.program_id = lm.program_id AND ls.control_flag = 'N'
AND lm.menu_id = #{menuId}
AND ls.program_id = #{programId} AND ls.system_service_id = #{systemServiceId}

SELECT /* Common.retrieveCommonCodeList */ code_type_code , common_code AS code , common_code_name AS name , parent_common_code AS p_code , language_code AS language_code FROM ( SELECT lct.code_type_code , lcc.common_code , lccm.language_code , lccm.common_code_name , lcc.parent_common_code , ROW_NUMBER() OVER (ORDER BY lct.code_type_code, lcc.sort_order_no, lcc.common_code) AS row_num FROM LGCOM_CODE_TYPE_CODE_C lct , LGCOM_COMMON_CODE_C lcc , LGCOM_COMMON_CODE_MULTI_LANG_C lccm WHERE lct.code_type_code = lcc.code_type_code AND lct.code_type_code = lccm.code_type_code AND lcc.common_code = lccm.common_code AND lcc.company_id = lccm.company_id AND lcc.inventory_organization_id = lccm.inventory_organization_id AND lcc.code_type_code = lccm.code_type_code AND lcc.use_flag = 'Y' AND lccm.language_code = #{USER_SESSION.languageCode} AND lcc.code_type_code = #{codeTypeCode} AND NVL(lcc.apply_start_date, SYSDATE) <= SYSDATE AND NVL(lcc.apply_end_date, SYSDATE) >= SYSDATE
AND lcc.parent_code_type_code = #{parentCodeTypeCode} AND lcc.parent_common_code = #{parentCommonCode}
AND lcc.common_code = #{commonCode}
UNION SELECT #{codeTypeCode} AS code_type_code , '' AS common_code , 'ALL' AS common_code_name , '' AS parent_common_code , -2 AS row_num FROM DUAL
UNION SELECT #{codeTypeCode} AS code_type_code , '' AS common_code , ' ' AS common_code_name , '' AS parent_common_code , -1 AS row_num FROM DUAL
) ORDER BY row_num, common_code

SELECT /* Common.retrieveFilteredCommonCodeList */ code_type_code , common_code AS code , common_code_name AS name , parent_common_code AS p_code , language_code AS language_code FROM ( SELECT lct.code_type_code , lcc.common_code , lccm.language_code , lccm.common_code_name , lcc.parent_common_code , ROW_NUMBER() OVER (ORDER BY lct.code_type_code, lcc.sort_order_no, lcc.common_code) AS row_num FROM LGCOM_CODE_TYPE_CODE_C lct , LGCOM_COMMON_CODE_C lcc , LGCOM_COMMON_CODE_MULTI_LANG_C lccm WHERE lct.code_type_code = lcc.code_type_code AND lct.code_type_code = lccm.code_type_code AND lcc.common_code = lccm.common_code AND lcc.company_id = lccm.company_id AND lcc.inventory_organization_id = lccm.inventory_organization_id AND lcc.code_type_code = lccm.code_type_code AND lcc.use_flag = 'Y' AND lccm.language_code = #{USER_SESSION.languageCode} AND lcc.code_type_code = #{codeTypeCode} AND NVL(lcc.apply_start_date, SYSDATE) <= SYSDATE AND NVL(lcc.apply_end_date, SYSDATE) >= SYSDATE
AND lcc.parent_code_type_code = #{parentCodeTypeCode} AND lcc.parent_common_code = #{parentCommonCode}
AND lcc.common_code = #{commonCode}
AND lcc.${filterColumn} = #{filterVallue}
) ORDER BY row_num, common_code

SELECT /* Common.retrieveValueSetList */ inquiry_terms_creation_sql_id as "SQL_ID" , inquiry_terms_crt_sql_name as "SQL_NAME" , system_code , module_code , source_column_name as "CHANGE_COLUMN" , meaning_column_name as "ALIAS_COLUMN" , sql_text as "SELECT" , from_sql_text as "FROM" , where_sql_text as "WHERE" , rule_sql_text as "GROUP_BY" , dynamic_sql_text as "ORDER_BY" FROM lgcom_inquiry_terms_crt_sql_m
WHERE NVL(apply_start_date, SYSDATE) <= SYSDATE AND NVL(apply_end_date, SYSDATE) >= SYSDATE
AND inquiry_terms_creation_sql_id = #{valueSetId}

SELECT /* Common.retrieveExportHeaderInfo */

      ATTRIBUTE${index + 1}

  FROM xxlge_export_info
 WHERE session_id = #{sessionId}
   AND ROWNUM = 1
   AND seq_no = 1

        SELECT /* Common.retrieveExportInfoCSV */

	          ATTRIBUTE${index + 1}

          FROM xxlge_export_info
         WHERE session_id = #{sessionId}
         ORDER BY seq_no

mapper.insert:
      INSERT /* Common.insertAttachFileInfo */
  INTO lgcom_attach_file_info
  (  file_id
    ,file_group_id
    ,system_code
    ,module_code
    ,file_name
    ,file_desc
    ,file_size
    ,file_location_info
    ,expiration_date
    ,archive_date
    ,archive_flag
    ,last_update_date
    ,last_updated_by
    ,creation_date
    ,created_by
) VALUES
(   #{fileId}
   ,#{fileGroupId}
   ,#{systemCode}
   ,#{moduleCode}
   ,#{fileName}
   ,#{fileDesc}           
   ,#{fileSize}
   ,#{fileLocationInfo}
   ,sysdate + (365*10)
   ,null
   ,'N'
   ,SYSDATE
   ,#{USER_SESSION.applicationUserId}
   ,SYSDATE
   ,#{USER_SESSION.applicationUserId}
)

INSERT /* Common.insertExcelUploadData */ INTO LGCOM_IMPORT_INFO ( SESSION_ID, SEQ_NO, CREATED_BY,
ATTRIBUTE${index + 1}
, ATTRIBUTE198 , CREATION_DATE ) VALUES ( #{sessionId}, #{seqNo}, #{USER_SESSION.applicationUserId},
#{item}
,#{programId} , SYSDATE )

INSERT INTO /* Common.insertExcelUploadLgcomTempData */ LGCOM_IMPORT_INFO_T ( session_id, seq_no, created_by,
attribute${index + 1}
, attribute198 , creation_date ) VALUES ( #{sessionId}, #{seqNo}, #{USER_SESSION.applicationUserId},
#{item}
, #{programId} , SYSDATE )
